"""LangGraph integration helper.

LangGraph orchestrates LangChain runnables, so the existing
``PRISMtraceCallbackHandler`` already captures every model / tool / chain
event a LangGraph workflow emits — LangGraph just hands callbacks down to
the underlying LangChain runtime.

This module is a thin convenience layer with two jobs:

1. Provide a ``PRISMtraceLangGraphHandler`` subclass that stamps emitted
   spans with an explicit ``[langgraph]`` label so the server-side
   architecture extractor renders these runs as LangGraph (not LangChain),
   and so trajectories in the Agent Runs UI are distinguishable.
2. Provide ``wrap_graph()`` which monkey-patches a compiled graph so the
   handler is automatically passed to every ``invoke`` / ``ainvoke`` /
   ``stream`` / ``astream`` call. Users do NOT have to remember the
   ``config={"callbacks": [...]}`` pattern at every call site.

Both are optional — you can also pass the handler directly:

    from prismtrace import PRISMtraceLangGraphHandler
    handler = PRISMtraceLangGraphHandler(api_key=..., project_id=...)
    result = graph.invoke(state, config={"callbacks": [handler]})

Status: Supported. The underlying callback flow is the same one used by
the production LangChain integration.
"""
from __future__ import annotations


from typing import Any

from .langchain_handler import PRISMtraceCallbackHandler

# Span-name prefix the server architecture extractor keys on to distinguish
# LangGraph runs from generic LangChain runs. Do NOT change this string
# without also updating backend/app/services/architecture_extractor.py.
_FRAMEWORK_TAG = "[langgraph]"


class PRISMtraceLangGraphHandler(PRISMtraceCallbackHandler):
    """LangChain-callback-compatible handler tagged for LangGraph traces.

    Subclass of ``PRISMtraceCallbackHandler`` that prefixes every emitted
    span name with ``[langgraph]``. The prefix is the signal the backend's
    architecture extractor uses to detect framework="langgraph". Behavior
    is otherwise identical to the production LangChain handler — same
    14 callback hooks, same flush path.
    """

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        kwargs.setdefault("source", "langgraph")
        super().__init__(*args, **kwargs)

    def _start_span(
        self,
        name: str,
        span_type: str,
        run_id: Any,
        input_text: str = "",
        parent_run_id: Any = None,
        **kwargs: Any,
    ) -> None:
        # Tag the span name so the server-side architecture extractor's
        # keyword match in label text picks up "langgraph". The original
        # name is preserved after the tag for human readability.
        tagged = f"{_FRAMEWORK_TAG} {name}" if not str(name).startswith(_FRAMEWORK_TAG) else name
        super()._start_span(
            tagged, span_type, run_id, input_text, parent_run_id, **kwargs
        )


def wrap_graph(graph: Any, handler: PRISMtraceLangGraphHandler) -> Any:
    """Attach ``handler`` to ``graph`` so every invocation is traced.

    LangGraph's compiled graphs accept ``config={"callbacks": [...]}`` at
    invoke time. This helper wraps ``invoke``, ``ainvoke``, ``stream``,
    and ``astream`` so the handler is auto-injected if the caller didn't
    pass their own callbacks. Existing callbacks in the user's config are
    preserved (the handler is appended, not replacing).

    Returns the same graph object, mutated in place. Re-wrapping is a
    no-op (already-tagged methods are detected and skipped) so calling
    ``wrap_graph`` twice is safe.
    """
    for method_name in ("invoke", "ainvoke", "stream", "astream"):
        if not hasattr(graph, method_name):
            continue
        original = getattr(graph, method_name)
        # Avoid re-wrapping if the helper was already applied.
        if getattr(original, "__prismtrace_wrapped__", False):
            continue

        def _make_wrapped(method: Any) -> Any:
            def _inject(config: Any) -> dict:
                config = config or {}
                callbacks = list(config.get("callbacks") or [])
                if handler not in callbacks:
                    callbacks.append(handler)
                return {**config, "callbacks": callbacks}

            def _wrapped(*args: Any, **kwargs: Any) -> Any:
                # ``config`` is the second positional parameter on every Pregel
                # entrypoint, and it can arrive either way. Writing it back as a
                # keyword unconditionally is what broke this: ``Pregel.invoke``
                # forwards config *positionally* to ``self.stream(...)``, which
                # this helper has also patched, so the caller ended up with both
                # a positional and a keyword config —
                # ``TypeError: Pregel.stream() got multiple values for argument
                # 'config'`` on plain ``graph.invoke(state)``. Update whichever
                # slot the value actually came in through.
                if len(args) >= 2:
                    args = (args[0], _inject(args[1]), *args[2:])
                else:
                    kwargs["config"] = _inject(kwargs.get("config"))
                return method(*args, **kwargs)
            _wrapped.__prismtrace_wrapped__ = True  # type: ignore[attr-defined]
            _wrapped.__name__ = getattr(method, "__name__", method_name)
            return _wrapped

        setattr(graph, method_name, _make_wrapped(original))
    return graph
